import type Redis from 'ioredis';

export interface BudgetPolicy {
  maxInputChars: number;
  maxOutputTokens: number;
  sessionTpmLimit: number;
  hourlyTenantBudgetUsd: number;
  inputUsdPer1MTokens: number;
  outputUsdPer1MTokens: number;
} 

export type GateDecision =
  | { allowed: true; estimatedMaxCostUsd: number; downgradedToLite: boolean }
  | { allowed: false; reason: 'INPUT_TOO_LONG' | 'SPONGE_ANOMALY' | 'TPM_EXCEEDED' | 'CIRCUIT_OPEN'; fallbackMessage: string };

function isLikelySpongePayload(text: string): boolean {
  // Phát hiện chuỗi ký tự lặp bất thường hoặc mật độ ký tự điều khiển/symbol quá cao (>35%)
  if (/(.)\1{25,}/.test(text)) return true;
  const nonWord = (text.match(/[^\p{L}\p{N}\s.,?!:;\-()]/gu) || []).length;
  return text.length > 200 && nonWord / text.length > 0.35;
}

export async function checkTokenBudgetGate(
  redis: Redis,
  tenantId: string,
  sessionKey: string,
  userText: string,
  historyTokenCount: number,
  policy: BudgetPolicy
): Promise<GateDecision> {
  if (userText.length > policy.maxInputChars) {
    return {
      allowed: false,
      reason: 'INPUT_TOO_LONG',
      fallbackMessage: `Tin nhắn vượt quá ${policy.maxInputChars} ký tự cho phép. Vui lòng rút gọn nội dung cần hỗ trợ.`,
    };
  }
  if (isLikelySpongePayload(userText)) {
    return {
      allowed: false,
      reason: 'SPONGE_ANOMALY',
      fallbackMessage: 'Nội dung chứa ký tự bất thường không thể xử lý. Vui lòng nhập văn bản tiếng Việt tiêu chuẩn.',
    };
  }

  // 1. Kiểm tra cầu dao ngân sách toàn Tenant theo cửa sổ giờ hiện tại
  const hourBucket = new Date().toISOString().slice(0, 13); // YYYY-MM-DDTHH
  const spendKey = `ai:spend:${tenantId}:${hourBucket}`;
  const circuitKey = `ai:circuit_open:${tenantId}`;
  const isCircuitOpen = await redis.get(circuitKey);
  if (isCircuitOpen === 'hard_stop') {
    return {
      allowed: false,
      reason: 'CIRCUIT_OPEN',
      fallbackMessage: 'Hệ thống AI đang tạm chuyển sang nhân viên tư vấn trực tiếp. Anh/chị vui lòng để lại SĐT để được hỗ trợ ngay.',
    };
  }

  // Ước tính token an toàn cho tiếng Việt (~1.3 ký tự/token ở biên xấu nhất)
  const estInputTokens = Math.ceil(userText.length / 1.3) + historyTokenCount;
  const estTotalTokens = estInputTokens + policy.maxOutputTokens;
  const estCostUsd =
    (estInputTokens / 1_000_000) * policy.inputUsdPer1MTokens +
    (policy.maxOutputTokens / 1_000_000) * policy.outputUsdPer1MTokens;

  // 2. Giới hạn TPM (Tokens Per Minute) riêng cho từng phiên / IP
  const minuteBucket = Math.floor(Date.now() / 60_000);
  const tpmKey = `ai:tpm:${tenantId}:${sessionKey}:${minuteBucket}`;
  const newTpm = await redis.incrby(tpmKey, estTotalTokens);
  if (newTpm === estTotalTokens) await redis.expire(tpmKey, 70);
  if (newTpm > policy.sessionTpmLimit) {
    return {
      allowed: false,
      reason: 'TPM_EXCEEDED',
      fallbackMessage: 'Bạn đang gửi yêu cầu quá nhanh. Vui lòng chờ 60 giây trước khi tiếp tục đặt câu hỏi.',
    };
  }

  // 3. Tích lũy chi phí tạm ứng (Pre-charge) và chốt hạ cấp / ngắt mạch nếu chạm ngưỡng
  const currentSpend = parseFloat(await redis.incrbyfloat(spendKey, estCostUsd.toFixed(6)));
  if (currentSpend <= estCostUsd + 0.0001) await redis.expire(spendKey, 3700);

  if (currentSpend >= policy.hourlyTenantBudgetUsd) {
    await redis.set(circuitKey, 'hard_stop', 'EX', 900); // Khóa mạch 15 phút & phát cảnh báo Ops
    return {
      allowed: false,
      reason: 'CIRCUIT_OPEN',
      fallbackMessage: 'Trợ lý tự động đang quá tải phiên. Nhân viên phụ trách sẽ liên hệ hỗ trợ anh/chị trong ít phút.',
    };
  }

  // Hạ cấp sang model Lite nếu chi phí đã vượt 75% trần giờ
  const downgradedToLite = currentSpend >= policy.hourlyTenantBudgetUsd * 0.75;
  return { allowed: true, estimatedMaxCostUsd: estCostUsd, downgradedToLite };
}
